package com.baraka.library;
import com.baraka.library.dto.Forms.*;
import com.baraka.library.entity.*;
import com.baraka.library.service.*;
import com.baraka.library.controller.LibraryController;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.test.context.support.WithMockUser;
import jakarta.validation.Validator;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestBuilders.*;
@SpringBootTest @AutoConfigureMockMvc
class LibraryIntegrationTest {
 static final Path TEMP;static {try{TEMP=Files.createTempDirectory("baraka-test-");}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->"jdbc:sqlite:"+TEMP.resolve("test.db")+"?foreign_keys=on&busy_timeout=10000&journal_mode=WAL");r.add("baraka.backup-directory",()->TEMP.resolve("backups").toString());}
 @Autowired LibraryService lib;@Autowired ReminderService reminders;@Autowired BackupService backups;@Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;@Autowired Validator validator;
 @BeforeEach void reset(){for(String t:List.of("reminder_logs","renewals","loans","books","borrowers","users"))jdbc.update("DELETE FROM "+t);jdbc.update("UPDATE settings SET default_days=14,max_renewals=2,lead_days=1,backup_keep=14,backup_directory=?,international_phones=0",TEMP.resolve("backups").toString());UserForm admin=new UserForm();admin.username="admin";admin.fullName="المدير";admin.password="safe-long-password";lib.createUser(admin,true);}
 Book book(int copies){BookForm b=new BookForm();b.title="مقدمة ابن خلدون";b.author="ابن خلدون";b.category="تاريخ";b.totalCopies=copies;return lib.saveBook(null,b);}
 Borrower borrower(){BorrowerForm b=new BorrowerForm();b.fullName="أحمد الإدريسي";b.phoneNumber="0612345678";b.whatsappNumber="0612345678";b.whatsappConsent=true;return lib.saveBorrower(null,b);}
 Loan loan(Book b,Borrower br){LoanForm f=new LoanForm();f.bookId=b.id;f.borrowerId=br.id;f.loanDate=lib.today();f.dueDate=lib.today().plusDays(1);return lib.borrow(f);}
 @Test void createBookAndAvailability(){Book b=book(2);assertEquals(2,lib.available(b));loan(b,borrower());assertEquals(1,lib.available(b));assertEquals(2,lib.books().findById(b.id).orElseThrow().totalCopies);}
 @Test void requiredFieldsAndQuantitiesValidated(){BookForm f=new BookForm();f.totalCopies=-1;assertTrue(validator.validate(f).size()>=4);assertThrows(IllegalArgumentException.class,()->lib.saveBook(null,f));}
 @Test void duplicateIsbnRejected(){BookForm f=new BookForm();f.title="كتاب";f.author="مؤلف";f.category="عام";f.isbn="123";lib.saveBook(null,f);assertThrows(IllegalArgumentException.class,()->lib.saveBook(null,f));}
 @Test void borrowerNormalizationAndValidation(){assertEquals("+212612345678",borrower().whatsappNumber);assertThrows(IllegalArgumentException.class,()->lib.normalizePhone("123",false));assertThrows(IllegalArgumentException.class,()->lib.normalizePhone("+33612345678",false));assertEquals("+33612345678",lib.normalizePhone("+33612345678",true));}
 @Test void cannotBorrowUnavailable(){Book b=book(1);Borrower br=borrower();loan(b,br);assertThrows(IllegalArgumentException.class,()->loan(b,br));assertEquals(1,lib.loans().count());}
 @Test void cannotBorrowArchivedOrDisabled(){Book b=book(2);Borrower br=borrower();lib.disableBorrower(br.id);assertThrows(IllegalArgumentException.class,()->loan(b,br));Borrower br2=borrower();lib.archive(b.id);assertThrows(IllegalArgumentException.class,()->loan(b,br2));}
 @Test void invalidDatesRejected(){LoanForm f=new LoanForm();f.bookId=book(1).id;f.borrowerId=borrower().id;f.loanDate=lib.today();f.dueDate=f.loanDate;assertThrows(IllegalArgumentException.class,()->lib.borrow(f));f.bookId=99999L;assertThrows(IllegalArgumentException.class,()->lib.borrow(f));}
 @Test void returnsRestoreAvailabilityAndCannotRepeat(){Book b=book(1);Loan l=loan(b,borrower());lib.returnLoan(l.id);assertEquals(1,lib.available(b));assertNotNull(lib.loan(l.id).returnedAt);assertThrows(IllegalArgumentException.class,()->lib.returnLoan(l.id));}
 @Test void renewalLimitsAndOriginalDatesPreserved(){Loan l=loan(book(1),borrower());LocalDate original=l.dueDate;lib.renew(l.id,original.plusDays(14));lib.renew(l.id,original.plusDays(28));assertEquals(original,lib.renewals().findByLoanIdOrderByRenewedAtDesc(l.id).getLast().oldDueDate);assertEquals(2,lib.loan(l.id).renewalCount);assertThrows(IllegalArgumentException.class,()->lib.renew(l.id,original.plusDays(42)));}
 @Test void overdueIsDynamicAndReturnedExcluded(){Loan l=loan(book(1),borrower());jdbc.update("UPDATE loans SET loan_date=?,due_date=? WHERE id=?",lib.today().minusDays(15).toString(),lib.today().minusDays(1).toString(),l.id);assertTrue(lib.loan(l.id).overdue(lib.today()));lib.returnLoan(l.id);assertFalse(lib.loan(l.id).overdue(lib.today()));}
 @Test void copiesCannotDropBelowActiveLoans(){Book b=book(2);loan(b,borrower());BookForm f=new BookForm();f.title=b.title;f.author=b.author;f.category=b.category;f.totalCopies=0;assertThrows(IllegalArgumentException.class,()->lib.saveBook(b.id,f));}
 @Test void remindersAndUrlEncoding(){Loan l=loan(book(1),borrower());assertEquals(1,reminders.eligible().size());var r=reminders.prepare(l.id);assertEquals("PREPARED",r.status);String url=reminders.open(r.id);assertTrue(url.startsWith("https://wa.me/212612345678?text="));assertEquals(r.message,java.net.URLDecoder.decode(url.substring(url.indexOf("text=")+5),java.nio.charset.StandardCharsets.UTF_8));assertNull(reminders.detail(r.id).manuallyConfirmedSentAt);reminders.confirm(r.id);assertNotNull(reminders.detail(r.id).manuallyConfirmedSentAt);}
 @Test void consentCheckedAgainAtOpening(){Loan l=loan(book(1),borrower());var r=reminders.prepare(l.id);jdbc.update("UPDATE borrowers SET whatsapp_consent=0 WHERE id=?",l.borrower.id);assertThrows(IllegalArgumentException.class,()->reminders.open(r.id));}
 @Test void futureLoansExcludedAndTodayClassified(){Loan l=loan(book(1),borrower());jdbc.update("UPDATE loans SET due_date=? WHERE id=?",lib.today().plusDays(5).toString(),l.id);assertTrue(reminders.eligible().isEmpty());jdbc.update("UPDATE loans SET due_date=? WHERE id=?",lib.today().toString(),l.id);assertEquals("DUE_TODAY",reminders.type(lib.loan(l.id)));}
 @Test void databaseIsPersistentOnIndependentConnection()throws Exception{Book b=book(3);try(var c=java.sql.DriverManager.getConnection("jdbc:sqlite:"+TEMP.resolve("test.db"));var s=c.createStatement();var r=s.executeQuery("SELECT title FROM books WHERE id="+b.id)){assertTrue(r.next());assertEquals(b.title,r.getString(1));}}
 @Test void concurrentBorrowersNeverExceedCapacity()throws Exception{Book b=book(1);Borrower br=borrower();try(var pool=Executors.newFixedThreadPool(4)){CountDownLatch start=new CountDownLatch(1);List<Future<Boolean>> results=new ArrayList<>();for(int i=0;i<4;i++)results.add(pool.submit(()->{start.await();try{loan(b,br);return true;}catch(RuntimeException e){return false;}}));start.countDown();int successes=0;for(var result:results)if(result.get(20,TimeUnit.SECONDS))successes++;assertEquals(1,successes);assertEquals(1,lib.loans().countByBookIdAndStatus(b.id,"ACTIVE"));}}
 @Test void backupIsConsistentAndValidated()throws Exception{Book b=book(2);Path backup=backups.backup();BackupService.validate(backup);try(var c=java.sql.DriverManager.getConnection("jdbc:sqlite:"+backup);var s=c.createStatement();var r=s.executeQuery("SELECT title FROM books WHERE id="+b.id)){assertTrue(r.next());assertEquals(b.title,r.getString(1));}}
 @Test void retentionAlwaysPreservesJustCreatedBackup()throws Exception{jdbc.update("UPDATE settings SET backup_keep=1 WHERE id=1");backups.backup();Path newest=backups.backup();assertTrue(Files.isRegularFile(newest));assertEquals(1,backups.list().size());}
 @Test void csvFormulaInjectionNeutralized(){assertEquals("\"'=2+2\"",LibraryController.csv("=2+2"));assertEquals("\"'  @SUM(A1)\"",LibraryController.csv("  @SUM(A1)"));assertEquals("\"a\"\"b\"",LibraryController.csv("a\"b"));}
 @Test void authenticationAndCsrf()throws Exception{mvc.perform(get("/books")).andExpect(status().is3xxRedirection());mvc.perform(formLogin().user("admin").password("safe-long-password")).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("/"));mvc.perform(formLogin().user("admin").password("wrong")).andExpect(redirectedUrl("/login?error"));mvc.perform(post("/books/new").with(user("admin").roles("ADMIN"))).andExpect(status().isForbidden());}
 @Test @WithMockUser(username="admin",roles="LIBRARIAN") void librarianDeniedAdminOperations()throws Exception{mvc.perform(get("/settings")).andExpect(status().isForbidden());mvc.perform(post("/backups").with(csrf())).andExpect(status().isForbidden());mvc.perform(get("/users")).andExpect(status().isForbidden());}
 @Test @WithMockUser(username="admin",roles="ADMIN") void allPagesRenderInArabicWithRealData()throws Exception{Book b=book(2);Borrower br=borrower();Loan l=loan(b,br);long r=reminders.prepare(l.id).id;for(String path:List.of("/","/books","/books/new","/books/"+b.id,"/books/"+b.id+"/edit","/borrowers","/borrowers/new","/borrowers/"+br.id,"/borrowers/"+br.id+"/edit","/loans","/returns","/loans/new","/loans/"+l.id,"/reminders","/reminders/"+r,"/reports","/settings","/users")){mvc.perform(get(path)).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("lang=\"ar\"")));}}
 @Test @WithMockUser(username="admin",roles="ADMIN") void bookFormValidationAndPost()throws Exception{mvc.perform(post("/books/new").with(csrf()).param("title","").param("author","مؤلف").param("category","عام").param("totalCopies","-1")).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("عنوان الكتاب مطلوب")));mvc.perform(post("/books/new").with(csrf()).param("title","كتاب جديد").param("author","مؤلف").param("category","عام").param("totalCopies","1")).andExpect(status().is3xxRedirection());assertEquals(1,lib.books().count());}
 @Test void setupCannotBeRepeated()throws Exception{mvc.perform(get("/setup")).andExpect(redirectedUrl("/login"));mvc.perform(post("/setup").with(csrf()).param("setupToken","bad").param("username","hacker").param("fullName","name").param("password","long-enough-password")).andExpect(redirectedUrl("/login"));assertEquals(1,lib.users().count());}
 @Test void firstRunPageAndInvalidToken()throws Exception{jdbc.update("DELETE FROM users");mvc.perform(get("/setup")).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("setupToken")));mvc.perform(post("/setup").with(csrf()).param("setupToken","invalid").param("username","admin").param("fullName","مدير").param("password","long-safe-password")).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("رمز الإعداد غير صحيح")));assertEquals(0,lib.users().count());}
 @Test void archiveExcludesAvailableDashboardCopies(){Book b=book(3);assertEquals(3,lib.availableTotal());lib.archive(b.id);assertEquals(0,lib.availableTotal());}
 @Test void lastAdministratorCannotBeDemoted(){long id=lib.users().findByUsername("admin").orElseThrow().id;assertThrows(IllegalArgumentException.class,()->lib.editUser(id,"مدير","LIBRARIAN"));}
 @Test void backupRejectsCorruptedSchema()throws Exception{Path p=backups.backup();try(var c=java.sql.DriverManager.getConnection("jdbc:sqlite:"+p);var s=c.createStatement()){s.execute("UPDATE schema_version SET checksum='invalid'");}assertThrows(IllegalArgumentException.class,()->BackupService.validate(p));}
 @Test void databaseTriggerRejectsOverCapacity(){Book b=book(1);Borrower br=borrower();Loan l=loan(b,br);assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("INSERT INTO loans(book_id,borrower_id,loan_date,due_date,status,renewal_count,created_at,updated_at) SELECT book_id,borrower_id,loan_date,due_date,status,renewal_count,created_at,updated_at FROM loans WHERE id=?",l.id));assertEquals(1,lib.loans().count());}
 @Test @WithMockUser(username="admin",roles="ADMIN") void rejectsInvalidLogoAndRendersFriendlyError()throws Exception{var file=new org.springframework.mock.web.MockMultipartFile("file","fake.png","image/png","not an image".getBytes());mvc.perform(multipart("/settings/logo").file(file).with(csrf())).andExpect(status().isBadRequest()).andExpect(content().string(org.hamcrest.Matchers.containsString("ملف الصورة غير صالح")));mvc.perform(get("/books/999999")).andExpect(status().isBadRequest()).andExpect(content().string(org.hamcrest.Matchers.containsString("الكتاب غير موجود")));}
 @Test void dueMessageDistinguishesTomorrowAndToday(){Loan l=loan(book(1),borrower());assertTrue(reminders.message(l).contains("غدًا"));jdbc.update("UPDATE loans SET due_date=? WHERE id=?",lib.today().toString(),l.id);assertTrue(reminders.message(lib.loan(l.id)).contains("اليوم"));}
}
